set tempo 90
set octave 4

chords cadence = 2m7 5dom7|1maj7 -

with key C { play piano: chords cadence }
with key F { play piano: chords cadence }
with key Bb { play piano: chords cadence }

set tempo 90

pattern cadence = {
  with octave 4 { piano: chords 2m7|5dom7|1maj7, },
  with octave 2 { bass: notes 2-------6-------|5-------7-------|1---------------, }
}

with key C { play cadence }
with key F { play cadence }
with key Bb { play cadence }

set tempo 90

chords turn = 2m7|5dom7|1maj7|1maj7
notes roots = 2---------------|5---------------|1---------------|1---------------

block cadence = {
  with octave 4 { piano: chords turn, },
  with octave 2 { piano: notes roots, },
}

with key C { play cadence }
with key F { play cadence }
with key Bb { play cadence }
